use std::collections::VecDeque;
use std::sync::Arc;
use std::sync::Mutex;

/// A bounded FIFO queue implemented using `VecDeque`.
///
/// This module provides a thread-safe bounded queue that enforces a maximum capacity.
/// When the queue is full, `push` will return `false` and the new element will not be added.
/// `pop` will return `None` if the queue is empty.
///
/// # Examples
///
/// ```
/// use bounded_queue::BoundedQueue;
/// let mut q = BoundedQueue::new(3);
/// q.push(1);
/// q.push(2);
/// q.push(3);
/// assert!(!q.push(4)); // Queue is full
/// assert_eq!(q.pop(), Some(1));
/// ```
pub struct BoundedQueue<T>

